IF OBJECT_ID('AD_FACE_AUTH_LOG', 'U') IS NULL BEGIN CREATE TABLE AD_FACE_AUTH_LOG (ID BIGINT IDENTITY(1,1) PRIMARY KEY, USER_ID NVARCHAR(50), STATUS NVARCHAR(50), MESSAGE NVARCHAR(500), MATCH_DISTANCE FLOAT, IP_ADDRESS NVARCHAR(50), USER_AGENT NVARCHAR(500), CREATED_DATE DATETIME DEFAULT GETDATE(), CREATED_BY NVARCHAR(50), UPDATED_DATE DATETIME, UPDATED_BY NVARCHAR(50), IS_ACTIVE BIT DEFAULT 1); END
